#[must_use]
pub fn upstream(provider: UpstreamProvider) -> ProviderCapabilities {
    provider.subscription_provider().map_or(
        ProviderCapabilities {
            temperature: Capability::Unknown,
            top_p: Capability::Unknown,
            stop_sequences: Capability::Unknown,
            output_token_limit: Capability::Unknown,
            reasoning: Capability::Unknown,
            web_search: Capability::Unknown,
            web_fetch: Capability::Unknown,
        },
        |provider| subscription(provider, None),
    )
}

/// Whether the selected Claude model uses the current adaptive-thinking wire
/// format instead of a caller-provided fixed token budget.
///
/// This is exact reviewed protocol evidence, not a version parser. Anthropic's
/// model documentation says which concrete IDs accept adaptive thinking; an
/// unfamiliar snapshot or compatible-provider ID remains unknown and cannot
/// inherit the capability from digits or a family prefix.
/// The versioned evidence manifest records its direct-provider source, product,
/// protocol, and review date.

#[must_use]
pub fn claude_uses_adaptive_thinking(model: crate::translation_core::Maybe<&crate::translation_core::Str>) -> bool {
    let Some(model) = model else {
        return false;
    };
    adaptive_thinking_evidence()
        .models
        .iter()
        .any(|advertised| advertised == model)
}

fn adaptive_thinking_evidence() -> &'static AdaptiveThinkingEvidence {
    static EVIDENCE: OnceLock<AdaptiveThinkingEvidence> = OnceLock::new();
    EVIDENCE.get_or_init(|| {
        let evidence: AdaptiveThinkingEvidence = serde_json::from_str(include_str!(
            "../docs/provider-evidence/anthropic-adaptive-thinking.json"
        ))
        .expect("checked Anthropic adaptive-thinking evidence must be valid JSON");
        assert_eq!(
            evidence.source_kind, "provider_owned_versioned_document",
            "adaptive-thinking evidence must retain a direct-provider source kind"
        );
        assert!(
            evidence
                .source_url
                .starts_with("https://platform.claude.com/"),
            "adaptive-thinking evidence must retain its provider-owned source"
        );
        assert!(!evidence.verified_at.is_empty());
        assert_eq!(evidence.product, "Anthropic Messages API");
        assert_eq!(evidence.wire_protocol, "anthropic-messages");
        evidence
    })
}

#[must_use]
pub fn unsupported_server_tool_type(
    provider: SubscriptionProvider,
    tools: crate::translation_core::Maybe<&crate::translation_core::Json>,
) -> crate::translation_core::Maybe<String> {
    let capabilities = subscription(provider, None);
    tools?.as_array()?.iter().find_map(|tool| {
        let kind = tool.get("type").and_then(crate::translation_core::Json::as_str)?;
        let support = if kind == "web_search" || kind.starts_with("web_search_") {
            capabilities.web_search
        } else if kind == "web_fetch" || kind.starts_with("web_fetch_") {
            capabilities.web_fetch
        } else {
            return None;
        };
        (support == Capability::Unsupported).then(|| kind.to_string())
    })
}

/// Whether a request forces a tool call it can never satisfy.
///
/// `tool_choice: any`/`required` demands a *function* call, but server-side
/// tools such as `web_search` are executed by the backend and never surface as
/// one. A request carrying only server tools therefore leaves the upstream with
/// no way to comply, which is how the reported request stalled instead of
/// answering.

#[must_use]
pub fn unsatisfiable_forced_tool_choice(tools: crate::translation_core::Maybe<&crate::translation_core::Json>, forced: bool) -> crate::translation_core::Maybe<String> {
    if !forced {
        return None;
    }
    let tools = tools?.as_array()?;
    if tools.is_empty() {
        return None;
    }
    let has_function = tools.iter().any(|tool| {
        let kind = tool.get("type").and_then(crate::translation_core::Json::as_str).unwrap_or("custom");
        !(kind.starts_with("web_search") || kind.starts_with("web_fetch"))
    });
    (!has_function).then(|| {
        "tool_choice requires a tool call, but the request offers only server-side tools that the \
         provider executes itself; use tool_choice auto or add a client tool"
            .to_string()
    })
}

